// ===== CONFIG =====
const PRIMARY_KEYWORD =
  items[0].json.primary_keyword || items[0].json.keyword || "";

const MIN_VOLUME = 20;
const MAX_PER_GROUP = 5;

// Normalize
const normalize = str =>
  (str || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, "")
    .trim();

const tokenize = str =>
  normalize(str).split(" ").filter(w => w.length > 2);

// Semantic relevance (soft)
const isSemanticallyRelated = (kw, primary) => {
  const p = tokenize(primary);
  const k = tokenize(kw);
  if (!p.length) return true;
  return p.some(t => k.includes(t));
};

// Intent compatibility
const isIntentCompatible = (intent = "") =>
  intent.includes("informational") || intent.includes("commercial");

// Buckets
let secondary = [];
let supporting = [];

// Collect candidates
for (const item of items) {
  const {
    keyword,
    avgMonthlySearches = 0,
    intent = ""
  } = item.json;

  if (!keyword) continue;
  if (normalize(keyword) === normalize(PRIMARY_KEYWORD)) continue;
  if (!isSemanticallyRelated(keyword, PRIMARY_KEYWORD)) continue;
  if (!isIntentCompatible(intent)) continue;
  if (avgMonthlySearches < MIN_VOLUME) continue;

  const entry = { keyword, volume: avgMonthlySearches };

  if (avgMonthlySearches >= 100) {
    secondary.push(entry);
  } else {
    supporting.push(entry);
  }
}

// Sort by volume
secondary.sort((a, b) => b.volume - a.volume);
supporting.sort((a, b) => b.volume - a.volume);

// 🔁 FILL-UP secondary if less than 5
if (secondary.length < MAX_PER_GROUP) {
  const needed = MAX_PER_GROUP - secondary.length;
  secondary = secondary.concat(supporting.slice(0, needed));
  supporting = supporting.slice(needed);
}

// 🔁 FILL-UP supporting if less than 5
if (supporting.length < MAX_PER_GROUP) {
  const usedKeywords = new Set(
    secondary.map(k => k.keyword).concat(supporting.map(k => k.keyword))
  );

  const extras = items
    .map(i => i.json)
    .filter(
      k =>
        k.keyword &&
        !usedKeywords.has(k.keyword) &&
        normalize(k.keyword) !== normalize(PRIMARY_KEYWORD)
    )
    .map(k => ({ keyword: k.keyword, volume: k.avgMonthlySearches || 0 }))
    .sort((a, b) => b.volume - a.volume);

  supporting = supporting.concat(
    extras.slice(0, MAX_PER_GROUP - supporting.length)
  );
}

// Final clean output
return [
  {
    json: {
      primary_keyword: PRIMARY_KEYWORD,
      secondary_keywords: secondary
        .slice(0, MAX_PER_GROUP)
        .map(k => k.keyword),
      other_relevant_keywords: supporting
        .slice(0, MAX_PER_GROUP)
        .map(k => k.keyword)
    }
  }
];

const results = [];

// ----------------------------
// Noise filters
// ----------------------------

// Navigation / footer noise
const NAV_KEYWORDS = [
  "platform", "resources", "company", "product", "solutions",
  "pricing", "careers", "blog", "hubs", "author",
  "request a demo", "see", "explore", "meet the",
  "startups", "global", "engineering", "finance", "hr", "it",
  "contents", "see also", "references", "external links", "further reading"
];

// CTA / marketing noise
const CTA_PATTERNS = [
  "request", "discover", "in action", "ensure your"
];

for (const item of items) {
  const title = Array.isArray(item.json.title)
    ? item.json.title.join(" ")
    : item.json.title || "";

  const headings = Array.isArray(item.json.headings)
    ? item.json.headings
    : [];

  let currentSection = null;
  const outline = [];

  for (const raw of headings) {
    if (!raw) continue;

    const text = raw.replace(/\s+/g, " ").trim();
    const lower = text.toLowerCase();

    if (!text) continue;
    if (text.length > 160) continue;

    // Skip navigation / footer noise
    if (NAV_KEYWORDS.some(k => lower === k || lower.startsWith(k + " "))) {
      continue;
    }

    // Skip CTAs
    if (CTA_PATTERNS.some(p => lower.includes(p))) {
      continue;
    }

    const isNumbered = /^\d+\./.test(text);

    // ----------------------------
    // Primary H2 detection (marketing / blog)
    // ----------------------------
    const isLikelyH2 =
      lower.includes("what is") ||
      lower.includes("types of") ||
      lower.includes("how to") ||
      lower.includes("comparison") ||
      lower.includes("methodology") ||
      lower.includes("deep dive") ||
      lower.includes("challenges") ||
      lower.includes("benefits") ||
      lower.includes("use cases") ||
      lower.includes("best") ||
      lower.includes("top") ||
      text.endsWith("?");

    // ----------------------------
    // Fallback H2 detection (Wikipedia / docs / RFCs)
    // ----------------------------
    const isFallbackH2 =
      !currentSection &&
      text.split(" ").length <= 6 &&
      /^[A-Z]/.test(text) &&
      !NAV_KEYWORDS.includes(lower);

    // ----------------------------
    // H3 detection
    // ----------------------------
    const isLikelyH3 =
      isNumbered ||
      (
        currentSection &&
        text.split(" ").length <= 8 &&
        !lower.includes("what is") &&
        !lower.includes("how to")
      );

    // ----------------------------
    // Apply hierarchy
    // ----------------------------
    if (isLikelyH2 || isFallbackH2) {
      currentSection = { h2: text, h3: [] };
      outline.push(currentSection);
      continue;
    }

    if (isLikelyH3 && currentSection) {
      currentSection.h3.push(text);
    }
  }

  // ----------------------------
  // SAFETY NET: never return empty
  // ----------------------------
  if (outline.length === 0 && headings.length) {
    outline.push({
      h2: title || "Overview",
      h3: headings.slice(0, 10)
    });
  }

  // ----------------------------
  // Flatten for downstream nodes
  // ----------------------------
  for (const section of outline) {
    results.push({
      json: {
        title,
        h2: section.h2,
        h3: Array.isArray(section.h3) ? section.h3.join(" | ") : ""
      }
    });
  }
}

return results;

const rows = [];

const data = items[0].json.output;

let isFirstRow = true;

for (const section of data.outline) {
  rows.push({
    json: {
      title: isFirstRow ? (data.title || "") : "",
      h1: isFirstRow ? (data.h1 || "") : "",
      h2: section.h2 || "",

      // Each H3 on a new line
      h3: Array.isArray(section.h3)
        ? section.h3.join("\n")
        : "",

      // Each FAQ on a new line (only in first row)
      faqs: isFirstRow && Array.isArray(data.faqs)
        ? data.faqs.join("\n")
        : ""
    }
  });

  isFirstRow = false;
}

return rows;

const rows = [];

for (const item of items) {
  rows.push({
    json: {
      primary_keyword: item.json.primary_keyword || "",

      // each keyword on a new line
      secondary_keywords: Array.isArray(item.json.secondary_keywords)
        ? item.json.secondary_keywords.join("\n")
        : "",

      other_relevant_keywords: Array.isArray(item.json.other_relevant_keywords)
        ? item.json.other_relevant_keywords.join("\n")
        : ""
    }
  });
}

return rows;

const blockedDomains = [
  // Communities
  'reddit.com',
  'quora.com',
  'stackoverflow.com',
  'stackexchange.com',
  'spiceworks.com',
  'community.ptc.com',
  'community.okta.com',
  'community.cloudflare.com',

  // Analyst / Research
  'gartner.com',
  'gartnerpeerinsights.com',
  'forrester.com',
  'idc.com',

  // Review Sites
  'g2.com',
  'trustpilot.com',
  'capterra.com',
  'getapp.com',
  'softwareadvice.com',
  'glassdoor.com',

  // Social Media
  'linkedin.com',
  'facebook.com',
  'twitter.com',
  'x.com',

  // Other problematic sites
  'medium.com',
  'saner.ai',
  'hipaajournal.com',
  'withpersona.com',
  'thectoclub.com',

  // Frequently protected by anti-bot systems
  'ticketmaster.com',
  'stubhub.com',
  'nike.com',
  'bestbuy.com',

  // Documentation sites that often rate-limit
  'learn.microsoft.com',
  'developers.cloudflare.com',
  'supertokens.com',
  'rfideas.com',

  // Block Cloudflare learning pages
  'cloudflare.com'
];

const urls = [];
const seen = new Set();

for (const item of items) {

  const results = item.json.urls || [];

  for (const result of results) {

    const url = result.link;

    if (!url) continue;

    const lowerUrl = url.toLowerCase();

    const isBlocked = blockedDomains.some(domain =>
      lowerUrl.includes(domain)
    );

    if (isBlocked) continue;

    // Remove duplicates
    if (seen.has(lowerUrl)) continue;

    seen.add(lowerUrl);

    urls.push({
      json: {
        link: url
      }
    });
  }
}

// Return first 6 usable competitor URLs
return urls.slice(0, 6);

const grouped = {};

let primary_keyword = "";
let secondary_keywords = [];
let other_relevant_keywords = [];

for (const item of items) {

  // Capture keyword data
  if (item.json.primary_keyword) {
    primary_keyword = item.json.primary_keyword;
    secondary_keywords = item.json.secondary_keywords || [];
    other_relevant_keywords = item.json.other_relevant_keywords || [];
    continue;
  }

  // Process competitor headings
  const title = item.json.title?.trim();
  const h2 = item.json.h2?.trim();
  const h3raw = item.json.h3?.trim();

  if (!title) continue;

  if (!grouped[title]) {
    grouped[title] = {
      title,
      outline: []
    };
  }

  if (!h2) continue;

  let h3 = [];

  if (h3raw) {
    h3 = h3raw
      .split("|")
      .map(v => v.replace(/^\d+\.\s*/, "").trim())
      .filter(Boolean);
  }

  const exists = grouped[title].outline.find(
    section => section.h2 === h2
  );

  if (!exists) {
    grouped[title].outline.push({
      h2,
      h3
    });
  }
}

// Build competitor signals
let competitorSignals = [];

Object.values(grouped).forEach((competitor) => {

  competitorSignals.push(
    `Competitor Title: ${competitor.title}`
  );

  competitor.outline.forEach((section) => {

    competitorSignals.push(
      `H2: ${section.h2}`
    );

    (section.h3 || []).forEach((sub) => {
      competitorSignals.push(
        `H3: ${sub}`
      );
    });

  });

});

// Final text for classifier
const textForClassification = `
Primary Keyword:
${primary_keyword}

Secondary Keywords:
${secondary_keywords.join(", ")}

Other Relevant Keywords:
${other_relevant_keywords.join(", ")}

Competitor Content Signals:
${competitorSignals.join("\n")}
`;

return [
  {
    json: {
      text_for_classification: textForClassification.trim()
    }
  }
];

const text = items[0].json.text_for_classification;

// -------- helpers ----------
const getSection = (label, nextLabel) => {
  const regex = new RegExp(
    `${label}:([\\s\\S]*?)${nextLabel ? nextLabel + ":" : "$"}`
  );
  const match = text.match(regex);
  return match ? match[1].trim() : "";
};

// -------- keyword extraction ----------
const primary_keyword = getSection("Primary Keyword", "Secondary Keywords")
  .split("\n")[0]
  .trim();

const secondary_keywords = getSection("Secondary Keywords", "Other Relevant Keywords")
  .split(",")
  .map(k => k.trim())
  .filter(Boolean);

const other_relevant_keywords = getSection(
  "Other Relevant Keywords",
  "Competitor Content Signals"
)
  .split(",")
  .map(k => k.trim())
  .filter(Boolean);

// -------- competitor parsing ----------
const competitorBlock = getSection("Competitor Content Signals");
const competitorChunks = competitorBlock.split("Competitor Title:").slice(1);

const competitors = competitorChunks.map(chunk => {
  const lines = chunk.trim().split("\n").map(l => l.trim()).filter(Boolean);

  const title = lines.shift();

  const outline = [];
  let currentH2 = null;

  lines.forEach(line => {
    if (line.startsWith("H2:")) {
      currentH2 = {
        h2: line.replace("H2:", "").trim(),
        h3: []
      };
      outline.push(currentH2);
    } else if (line.startsWith("H3:") && currentH2) {
      currentH2.h3.push(line.replace("H3:", "").trim());
    }
  });

  return { title, outline };
});

// -------- final output ----------
return [
  {
    json: {
      primary_keyword,
      secondary_keywords,
      other_relevant_keywords,
      competitors
    }
  }
];

