const result = {
  primary_keyword: "",
  secondary_keywords: [],
  other_relevant_keywords: [],
  generated_outline: [],
  competitor_outline: []
};

for (const item of items) {

  // Keywords record
  if (item.json.primary_keyword) {
    result.primary_keyword = item.json.primary_keyword;

    result.secondary_keywords =
      typeof item.json.secondary_keywords === "string"
        ? item.json.secondary_keywords
            .split("\n")
            .map(k => k.trim())
            .filter(Boolean)
        : [];

    result.other_relevant_keywords =
      typeof item.json.other_relevant_keywords === "string"
        ? item.json.other_relevant_keywords
            .split("\n")
            .map(k => k.trim())
            .filter(Boolean)
        : [];
  }

  // Generated outline rows
  if (item.json.h2 || item.json.h3) {

    result.generated_outline.push({
      title: item.json.title || "",
      h2: item.json.h2 || "",
      h3: item.json.h3
        ? item.json.h3.split("|").map(v => v.trim()).filter(Boolean)
        : []
    });

  }

  // Competitor rows (if present)
  if (item.json.competitor_title) {

    result.competitor_outline.push({
      title: item.json.competitor_title,
      h2: item.json.competitor_h2 || "",
      h3: item.json.competitor_h3
        ? item.json.competitor_h3.split("|").map(v => v.trim())
        : []
    });

  }
}

return [
  {
    json: result
  }
];

const data = $input.all();

let result = {
  intent_type: "",
  primary_keyword: "",
  secondary_keywords: [],
  other_relevant_keywords: [],
  generated_outline: [],
  content_gap_analysis: {}
};

for (const item of data) {
  const json = item.json;

  // Primary Keyword
  if (json.primary_keyword) {
    result.primary_keyword = json.primary_keyword;
  }

  // Secondary Keywords
  if (json.secondary_keywords) {
    result.secondary_keywords = Array.isArray(json.secondary_keywords)
      ? json.secondary_keywords
      : String(json.secondary_keywords)
          .split("\n")
          .map(v => v.trim())
          .filter(Boolean);
  }

  // Other Relevant Keywords
  if (json.other_relevant_keywords) {
    result.other_relevant_keywords = Array.isArray(json.other_relevant_keywords)
      ? json.other_relevant_keywords
      : String(json.other_relevant_keywords)
          .split("\n")
          .map(v => v.trim())
          .filter(Boolean);
  }

  // Generated Outline Rows
  if (
    json.title ||
    json.h1 ||
    json.h2 ||
    json.h3 ||
    json.faqs
  ) {
    result.generated_outline.push({
      title: json.title || "",
      h1: json.h1 || "",
